options.styles:
.obstruction {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  overflow: hidden;
  gap: 6px;
}
.obstruction__map {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  object-fit: contain;
  image-rendering: pixelated;
}
.obstruction__meta {
  flex: 0 0 auto;
  font-size: 11px;
  line-height: 1.3;
  opacity: 0.7;
  text-align: center;
}
